CREATE TABLE IF NOT EXISTS public.match_feedback (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),supplier_id uuid NOT NULL REFERENCES public.suppliers(id),printed_description text NOT NULL,item_code text,unit text,unit_price numeric,bani_decision text,bani_product_id uuid REFERENCES public.product_master(id),chosen_product_id uuid REFERENCES public.product_master(id),user_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT ON public.match_feedback TO authenticated; GRANT ALL ON public.match_feedback TO service_role; ALTER TABLE public.match_feedback ENABLE ROW LEVEL SECURITY; CREATE INDEX IF NOT EXISTS match_feedback_supplier_recent ON public.match_feedback(tenant_id,supplier_id,created_at DESC); DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='match_feedback' AND policyname='match_feedback_read') THEN CREATE POLICY match_feedback_read ON public.match_feedback FOR SELECT TO authenticated USING (public.is_tenant_member(tenant_id,auth.uid()) OR public.is_platform_admin(auth.uid())); END IF; IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='match_feedback' AND policyname='match_feedback_insert') THEN CREATE POLICY match_feedback_insert ON public.match_feedback FOR INSERT TO authenticated WITH CHECK (user_id=auth.uid() AND (public.is_tenant_member(tenant_id,auth.uid()) OR public.is_platform_admin(auth.uid())) AND EXISTS(SELECT 1 FROM public.suppliers s WHERE s.id=supplier_id AND s.tenant_id=match_feedback.tenant_id) AND (bani_product_id IS NULL OR EXISTS(SELECT 1 FROM public.product_master p WHERE p.id=bani_product_id AND p.tenant_id=match_feedback.tenant_id)) AND (chosen_product_id IS NULL OR EXISTS(SELECT 1 FROM public.product_master p WHERE p.id=chosen_product_id AND p.tenant_id=match_feedback.tenant_id))); END IF; END $$;